def pair(ko, en):
    return {"ko": ko, "en": en}


def invariant(ident, owner, relation, basis="project_selected_scope"):
    return dict(id=ident, owner=owner, relation=relation, basis=basis)


def variant(ident, ko, en, status="authored_scope_preserving_draft"):
    return dict(id=ident, description=pair(ko, en), status=status,
                verification="not independently reviewed or image tested")


def case(ko, en, relation, why):
    return dict(request=pair(ko, en), semantic_relation=relation, rationale_ko=why)


def card(ident, family, profiles, title, meaning, scope, source_ids, invariant_rows,
         short, detailed, variants, positives, negatives, limits, gaps):
    assert len(variants) == len(positives) == len(negatives) == 3
    return dict(id=ident, family=family, profile_ids=profiles, title_ko=title,
                research_status="authored_draft_not_runtime_applied",
                contextual_meaning=meaning, selected_scope_ko=scope,
                source_ids=source_ids, invariants=invariant_rows,
                neutral_descriptions={"short": short, "detailed": detailed},
                variants=variants, positive_contexts=positives,
                contrast_contexts=negatives, claim_limits_ko=limits,
                remaining_evidence_gaps_ko=gaps)


