def main():
    stamp = datetime.now(timezone(timedelta(hours=9))).isoformat()
    dump("sources.json", {
        "schema_version": 1, "assembled_at_kst": stamp,
        "items": SOURCES,
        "reuse_limits": "Paraphrased research facts and links only; no remote image files or full copyrighted texts redistributed.",
        "unsuccessful_access": [
            {"url": "https://krdict.korean.go.kr/eng/dicSearch/search?mainSearchWord=%EC%9B%90%ED%94%BC%EC%8A%A4", "outcome": "tool fetch failed", "fact_status": "not used as a verified Korean definition"},
            {"url": "https://one-piece.com/", "outcome": "403", "fact_status": "not used as source evidence"},
            {"url": "https://www2.ic.daito.ac.jp/jtogashi/articles/togashi2009a.pdf", "outcome": "timeout/internal error", "fact_status": "indexed excerpt only; exact PDF wording needs review"},
            {"url": "https://www.flight.co.jp/uploaded_files/c_news/106_detail.pdf", "outcome": "text encoding damaged; browser viewport blank", "fact_status": "indexed excerpt only; not visual PDF verification"},
        ],
    })
    dump("concept-cards.json", {
        "schema_version": 1, "authored_at_kst": stamp,
        "baseline_head": SNAPSHOT["head"],
        "baseline_loaded_profiles": SNAPSHOT["loaded_profile_count"],
        "status": "research_drafts_unapplied",
        "scope": "12 agreed concept families; sheer/mesh and broad/short split into separate cards; two cowl profiles share one card",
        "provenance": "Context requests, neutral descriptions, variants and invariants are authored proposals grounded in linked sources and the frozen project profiles. They are not external quotations or independent evaluation results.",
        "cards": CARDS,
    })
    cases = []
    proposals = []
    for c in CARDS:
        for label, examples in [("positive", c["positive_contexts"]), ("contrast", c["contrast_contexts"])]:
            for number, ex in enumerate(examples, 1):
                cases.append(dict(
                    id=f"{c['id']}-{label}-{number:02d}", card_id=c["id"],
                    source_ids=c["source_ids"], candidate_profile_ids=c["profile_ids"],
                    request=ex["request"], semantic_relation=ex["semantic_relation"],
                    rationale_ko=ex["rationale_ko"],
                    expected_profile_ids=c["profile_ids"] if label == "positive" else [],
                    expected_relation_basis="authored comparison to frozen selected project scope; not measured activation",
                    split="authoring_development_examples_not_blind_holdout",
                    model_result="NOT_RUN", pixel_result="NOT_RUN"))
        neutral = [c["neutral_descriptions"][size][lang] for size in ("short", "detailed") for lang in ("ko", "en")]
        contrasts = [ex["request"][lang] for ex in c["contrast_contexts"] for lang in ("ko", "en")]
        for ident in c["profile_ids"]:
            p = BY_ID[ident]["profile"]
            proposals.append(dict(
                profile_id=ident, card_id=c["id"], source_ids=c["source_ids"],
                source_file=BY_ID[ident]["source_file"],
                baseline_compiled_profile_sha256=hashlib.sha256(json.dumps(p, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest(),
                status="unapplied_append_only_review_proposal",
                operations=[
                    {"operation": "append_unique", "path": "semantics.paraphrase_examples", "values": neutral},
                    {"operation": "append_unique", "path": "semantics.contrast_examples", "values": contrasts},
                    {"operation": "append_unique", "path": "semantics.claim_limits", "values": c["claim_limits_ko"]},
                ],
                unchanged_contracts=["semantics.definition", "activation", "runtime_expression", "authored_components", "required_evidence_fields", "evidence_requirements", "render_gates", "composition_instruction"],
                boundary="Paraphrase additions alone do not update literal evidence requirements, hard activation, frozen core choices or output wording. No change has been applied."))
    (OUT / "context-cases.jsonl").write_text("".join(json.dumps(c, ensure_ascii=False) + "\n" for c in cases))
    dump("profile-data-proposals.json", {
        "schema_version": 1, "baseline_head": SNAPSHOT["head"],
        "status": "NOT_APPLIED", "apply_script_included": False,
        "policy": "Review artifacts for existing data fields, not runtime schema or skill logic changes. An appendix may preserve additional source/variant metadata outside the runtime registry.",
        "proposals": proposals,
    })
    dump("reference-observations.json", {
        "schema_version": 1, "checked_on": "2026-10-02",
        "method": "Read-only normal page screenshot through Codex in-app browser; no remote image download, crop, enlargement or rehosting",
        "items": [
            {"id": "cowl-page-view", "source_id": "met-cowl", "card_id": "cowl-draped-opening",
             "observation_type": "normal_viewport_observation",
             "observed": ["밝은 색의 긴 의복에서 목둘레 주변의 천이 겹쳐 처지는 형태가 보인다.", "목둘레 부근의 처짐과 허리 아래 세로 천 주름은 위치가 구별된다."],
             "not_resolved": ["낮은 해상도에서 내부 부착 봉제선이나 재단 방향은 확정할 수 없다."],
             "catalog_facts_separate": ["비대칭의 스카프 같은 카울 목둘레는 소장품 설명의 사실이다."],
             "image_rights": "page explicitly restricts enlargement/full-screen/download; reference link and own observations only",
             "image_file_collected": False, "qualification": "reference observation, not generated-image acceptance"},
            {"id": "shirring-swatches-view", "source_id": "seamwork-shirring", "card_id": "local-gathered-folds",
             "observation_type": "normal_viewport_observation",
             "observed": ["세 파란 천 조각에서 여러 가로 줄 주변의 작은 세로 주름이 반복되어 보인다.", "모인 영역과 그 위의 더 넓게 펼쳐진 영역이 각각 같은 천 조각 안에서 이어진다."],
             "not_resolved": ["외관만으로 밑실의 탄성 재료나 인장 성능을 확인하지 못한다."],
             "catalog_facts_separate": ["탄성 밑실과 여러 봉제 줄의 제작 설명은 작성자의 튜토리얼 사실이다."],
             "image_rights": "copyrighted tutorial; no reuse license established; reference link and own observations only",
             "image_file_collected": False, "qualification": "related construction reference, not a universal ruching template"},
        ],
    })
    by_source = {s["id"]: s for s in SOURCES}
    lines = ["# 개념별 보강 자료", "", "이 문서는 concept-cards.json의 읽기용 표현이다. 모든 예문·변형은 출처와 현재 프로필을 바탕으로 작성한 연구 초안이다. 모델·픽셀 평가나 독립 전문가 검토는 실행하지 않았다.", ""]
    for number, c in enumerate(CARDS, 1):
        lines.extend([f"## {number}. {c['title_ko']}", "",
                      "대상 프로필: " + ", ".join(f"`{p}`" for p in c["profile_ids"]), "",
                      "**문맥상 뜻:** " + c["contextual_meaning"]["ko"], "",
                      "**현재 프로필의 선택 범위:** " + c["selected_scope_ko"], "",
                      "**근거:** " + ", ".join(f"[{by_source[s]['title']}]({by_source[s]['url']}) — {by_source[s]['access_status']}" for s in c["source_ids"]), "",
                      "**관계와 소유자:**", ""])
        lines.extend(f"- {i['owner']}: {i['relation']} (현재 프로젝트의 선택 조건)" for i in c["invariants"])
        for size, label in (("short", "짧은 묘사"), ("detailed", "상세 묘사")):
            lines.extend(["", f"**이름 없는 {label}:**", "",
                          "한국어: " + c["neutral_descriptions"][size]["ko"], "",
                          "English: " + c["neutral_descriptions"][size]["en"]])
        lines.extend(["", "**변형 초안:**", ""])
        lines.extend("- " + v["description"]["ko"] for v in c["variants"])
        lines.extend(["", "**선택 범위에 맞는 문맥 예시:**", ""])
        lines.extend("- " + v["request"]["ko"] + " / " + v["request"]["en"] for v in c["positive_contexts"])
        lines.extend(["", "**혼동 경계 예시:**", ""])
        lines.extend("- " + v["request"]["ko"] + " / " + v["request"]["en"] + f" — `{v['semantic_relation']}`: " + v["rationale_ko"] for v in c["contrast_contexts"])
        lines.extend(["", "**한계:**", ""])
        lines.extend("- " + v for v in c["claim_limits_ko"])
        lines.extend(["", "**추가 근거 공백:**", ""])
        lines.extend("- " + v for v in c["remaining_evidence_gaps_ko"])
        lines.append("")
    (OUT / "CONCEPTS.md").write_text("\n".join(lines))
    print(json.dumps({"sources": len(SOURCES), "families": len({c["family"] for c in CARDS}),
                      "cards": len(CARDS), "profiles": len(proposals), "variants": sum(len(c["variants"]) for c in CARDS),
                      "bilingual_cases": len(cases), "utterances": len(cases) * 2,
                      "neutral_texts": len(CARDS) * 4, "reference_observations": 2}, ensure_ascii=False))


if __name__ == "__main__":
    main()
